import React, { useEffect, useState } from "react";
import getpokemon from "../services/pokemon.services";
import ListPokemonCard from "../components/listPokemonImage";
import { PokemonProvider } from "../context/PokemonContext";
import ModalPokemon from "../components/ModalPokemon";




interface PokemonListProps {
    name: string
    url: string

}

const ListPokemon = () => {
    const [offset, setOffset] = useState(0)
    const [load, setload] = useState(false)
    const [listPokemon, setListPokemon] = useState<PokemonListProps[]>([])
    const [listSearchPokemon, setListSearchPokemon] = useState('')
    const [stopLoad, setStopLoad] = useState(true)
    const listFilterPokemon = listPokemon.filter(listPokemon => listPokemon.name.toLowerCase().includes(listSearchPokemon.toLowerCase()))
    // useEffect(()=>{
    //     getpokemon(data:PokemonListResponse)=>{
    //     setListPokemon(data.results)

    //     })
    // },[])
    useEffect(() => {
        setload(true)
        getpokemon({
            offset, callback: (data) => {
                setListPokemon((prev) => [...prev, ...data.results])
                setload(false)
                if (!data.next) {
                    setStopLoad(false)

                }
            }
        })
    }, [offset])



    useEffect(() => {
        const handleScroll = () => {
            if (window.innerHeight + window.scrollY >= document.body.scrollHeight - 1000 && !load && stopLoad) {
                setOffset(prev => prev + 30)
            }
        }
        window.addEventListener("scroll", handleScroll)
        return () => window.removeEventListener("scroll", handleScroll)


    }, [load, stopLoad])

    return (

        <div className="bg-[url('./images/bg.png')] w-full min-h-screen bg-cover bg-no-repeat bg-center">
            <h1 className="text-center text-2 text-2xl font-semibold capitalize ">List Pokemon</h1>
            <div>
                <div className="flex justify-center mt-5  ">
                    <input type="text" placeholder='Search Pokemon' className=' w-52 h-7 pl-2 md:w-72' value={listSearchPokemon} onChange={(e) => setListSearchPokemon(e.target.value)} />
                </div>
                <ul className=" grid grid-cols-2 mt-2 justify-items-center">
                    {

                        listFilterPokemon.map((list) =>
                                    <ListPokemonCard key={list.name} url={list.url} name={list.name} />

                        )}


                        
                </ul>
                
                {load && <div className="text-2xl font-bold text-center mt-4 text-blue-900">Loading Pokemon...</div>}
                {!stopLoad && <div className="text-2xl font-bold text-center mt-4 text-blue-900">Data Pokemon Habis</div>}


                    

            </div>
            <div>
                <ModalPokemon/>
            </div>
        </div>


    )

}
export default ListPokemon