import {createContext,useState,ReactNode } from "react";
interface PokemonListProps {
    pokemonSelected:any;
    setPokemonSelected:(pokemon:any)=>void;
    showModal:boolean
    setShowModal:(show:boolean)=>void
  }
  export const PokemonContext=createContext<PokemonListProps>({
    pokemonSelected:null,
    setPokemonSelected:()=>{},
    showModal:false,
    setShowModal:()=>{},
  })
  export const PokemonProvider =({children}:{children:ReactNode})=>{
    const [pokemonSelected, setPokemonSelected]=useState<any>(null)
    const[showModal,setShowModal]=useState(false);
    
    return(
    <PokemonContext.Provider
    value={{pokemonSelected,setPokemonSelected,showModal,setShowModal}}
    >
        {children}
    </PokemonContext.Provider>
    )
  }

