import axios from "axios";
import { PokemonListResponse } from "../data/types";


 interface listProps{
    offset:number
    callback:(data:PokemonListResponse)=>void
 }


const getpokemon = ({callback,offset}:listProps) =>{
    axios.get<PokemonListResponse>(`https://pokeapi.co/api/v2/pokemon?limit=30&offset=${offset}`).then((res)=>{
        setTimeout(()=>{
         callback(res.data) 
         console.log(res.data)
        },1000)
    
    }) 
.catch((err)=>{
 console.log("Eror Data Api",err)
})
}
export default getpokemon
