import { useContext, useState } from "react"
import { PokemonContext } from "../context/PokemonContext"
import list from "../img_list/arrow_back.png"
import ball from "../img_list/Pokeball.png"
import StatPokemon from "./StatPokemon";

const ModalPokemon = () => {
    const { pokemonSelected, showModal, setShowModal } = useContext(PokemonContext)
    if (!showModal || !pokemonSelected) return null
    return (

        <div className=" fixed inset-0 w-full min-h-[55] bg-green-500 ">
            <div className="flex gap-2">
                <div className="" onClick={() => setShowModal(false)}>
                    <img className="ml-3 mt-5" src={list} alt="this arrow" />
                </div>
                <div className=" text-white capitalize mt-5 text-2xl font-bold grow">{pokemonSelected.name}</div>
                <div className="mt-6 text-white mr-6 text-base fon font-bold">#{pokemonSelected.id}</div>
            </div>
            <div className="flex flex-col  ">
                <div className="flex justify-end ">
                    <img className="  relative -top-10 opacity-10  " src={ball} alt="ball" />
                </div>
                <div className="flex justify-center">
                    <img className="absolute w-48 top-32" src={pokemonSelected.image} alt={pokemonSelected.name} />
                </div>
                <div className="    border-2 h-screen rounded-lg mx-1 bg-white">
                    <div className=" justify-center gap-10 flex flex-row">
                        {pokemonSelected.types.map((t: any, id: number) => (
                            <p className="mt-12 h-8 border-2" key={id}>
                                {t.type.name}
                            </p>
                        ))}
                    </div>
                    <div>{pokemonSelected.deskripsi}</div>
                    <div className="text-center mt-3">About</div>
                    <div className="flex flex-row gap-6 justify-center mt-5">
                        <p className=" bg-[url('./img_list/weight.svg')] bg-contain h-7 bg-no-repeat pl-10"> {pokemonSelected.weight} Kg </p>
                        <div className="border-2 border-gray-300"></div>
                        <p className=" bg-[url('./img_list/straighten.svg')] bg-contain h-7 bg-no-repeat pl-10"> {pokemonSelected.height} m </p>
                         <div className="border-2 border-gray-300"></div>
                            <div className="flex flex-col"> {pokemonSelected.moves.slice(0,2).map((move: any, id: number) => (
                                <p className="" key={id}>
                                   {move.move.name}
                                </p>
                            ))}</div>
                            
                    </div>
                    <div className="flex flex-row justify-center gap-24 mt-1 text-gray-500">
                    <div>Weight</div>
                    <div>Height</div>
                    <div>Moves</div>
                    </div>
                    <div className="text-center mt-8">Base Stats</div>
                    <div>
                        {pokemonSelected.stats.map((stat:any,id:number)=>(
                            <div className="flex flex-row gap-2" key={id}>
                            <p className="text-green-600 capitalize">{stat.stat.name}</p>
                            <div>   
                            </div>
                             <p className="">{stat.base_stat}</p>
                            </div>
                        ))}
                        
                    </div>
                </div>

            </div>

        </div>


    )
}
export default ModalPokemon